import sqlite3
import json
import ast
from collections import defaultdict
from typing import Any, Dict, List, Tuple

# -------------------------
# Fixed configuration (as required)
# -------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}

# -------------------------
# Helpers
# -------------------------
def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn

def table_exists(conn: sqlite3.Connection, table: str) -> bool:
    cur = conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,))
    return cur.fetchone() is not None

def parse_maybe_dict(value: Any) -> Any:
    """Parse TEXT columns that may contain JSON or Python-literal dict strings."""
    if value is None:
        return None
    if isinstance(value, (dict, list)):
        return value
    if not isinstance(value, str):
        return value

    s = value.strip()
    if s == "" or s.lower() == "none":
        return None

    # Try JSON first
    try:
        return json.loads(s)
    except Exception:
        pass

    # Try python literal
    try:
        return ast.literal_eval(s)
    except Exception:
        return value  # leave as-is

def normalize_attributes(attrs_text: Any) -> Dict[str, Any]:
    attrs = parse_maybe_dict(attrs_text)
    if attrs is None:
        return {}
    if isinstance(attrs, dict):
        return attrs
    # Sometimes attributes can be something else; fallback
    return {}

def has_wifi(attrs: Dict[str, Any]) -> bool:
    # Yelp often uses 'WiFi': "free"/"paid"/"no"
    v = attrs.get('WiFi', None)
    if v is None:
        return False
    if isinstance(v, str):
        return v.strip().lower() in {"free", "paid"}
    if isinstance(v, bool):
        return v
    return False

def has_parking(attrs: Dict[str, Any]) -> bool:
    # Yelp commonly uses 'BusinessParking' as a dict (or stringified dict)
    bp = attrs.get('BusinessParking', None)
    bp = parse_maybe_dict(bp)
    if isinstance(bp, dict):
        return any(bool(x) for x in bp.values())

    # Some datasets may have other keys; best-effort fallback
    for k in ("Parking", "Garage Parking", "Street Parking", "Valet Parking"):
        if k in attrs and str(attrs.get(k)).lower() in ("true", "1", "yes"):
            return True
    return False

def chunked(iterable: List[Any], size: int = 800) -> List[List[Any]]:
    return [iterable[i:i+size] for i in range(0, len(iterable), size)]

# -------------------------
# Main logic
# -------------------------
def main():
    # Connect DBs
    biz_conn = connect_sqlite(sqlite_paths["business"])
    rev_conn = connect_sqlite(sqlite_paths["review"])
    user_conn = connect_sqlite(sqlite_paths["user"])

    try:
        # Basic table existence checks (adjust here if your table names differ)
        if not table_exists(biz_conn, "business"):
            raise RuntimeError("Table 'business' not found in business.db")
        if not table_exists(rev_conn, "review"):
            raise RuntimeError("Table 'review' not found in review.db")
        if not table_exists(user_conn, "user"):
            raise RuntimeError("Table 'user' not found in user.db")

        # Step 1: candidate Tucson hotels with stars>=4
        candidate_sql = """
            SELECT business_id, name, city, stars, categories, attributes,
                   address, state, postal_code
            FROM business
            WHERE city = ?
              AND stars >= ?
              AND (categories LIKE ? OR categories LIKE ?)
        """
        rows = biz_conn.execute(candidate_sql, ("Tucson", 4.0, "%Hotel%", "%Hotels%")).fetchall()

        # Step 2: parse attributes to keep only WiFi + parking
        hotels = []
        for r in rows:
            attrs = normalize_attributes(r["attributes"])
            if has_wifi(attrs) and has_parking(attrs):
                hotels.append({
                    "business_id": r["business_id"],
                    "name": r["name"],
                    "stars": r["stars"],
                    "address": r["address"],
                    "state": r["state"],
                    "postal_code": r["postal_code"],
                    "categories": r["categories"],
                    "wifi": attrs.get("WiFi"),
                    "business_parking": parse_maybe_dict(attrs.get("BusinessParking"))
                })

        business_ids = [h["business_id"] for h in hotels]

        print("=== Tucson hotels (stars>=4.0) with WiFi and parking ===")
        if not hotels:
            print("No matching hotels found.")
            return
        for h in sorted(hotels, key=lambda x: (-float(x["stars"]), x["name"])):
            print(f"- {h['name']} | stars={h['stars']} | {h['address']} {h['state']} {h['postal_code']} | WiFi={h['wifi']} | Parking={h['business_parking']}")

        # Step 3: find reviews mentioning 'clean' or 'comfortable'
        # Use chunking to avoid SQLite parameter limits
        matched_reviews = []
        review_sql_template = """
            SELECT review_id, user_id, business_id, date, stars, text
            FROM review
            WHERE business_id IN ({placeholders})
              AND (lower(text) LIKE '%clean%' OR lower(text) LIKE '%comfortable%')
        """
        for chunk in chunked(business_ids, size=800):
            placeholders = ",".join(["?"] * len(chunk))
            sql = review_sql_template.format(placeholders=placeholders)
            matched_reviews.extend(rev_conn.execute(sql, chunk).fetchall())

        print("\n=== Reviews mentioning 'clean' or 'comfortable' (within these hotels) ===")
        print(f"Matched reviews: {len(matched_reviews)}")

        # Aggregate by user
        user_stats = defaultdict(lambda: {
            "mentions": 0,
            "business_ids": set(),
            "example_snippets": []
        })
        for r in matched_reviews:
            uid = r["user_id"]
            user_stats[uid]["mentions"] += 1
            user_stats[uid]["business_ids"].add(r["business_id"])
            # keep a couple short snippets
            if len(user_stats[uid]["example_snippets"]) < 2:
                txt = (r["text"] or "").replace("\n", " ").strip()
                user_stats[uid]["example_snippets"].append(txt[:180])

        user_ids = list(user_stats.keys())

        # Step 4: fetch user details and print top users by mentions
        users = {}
        if user_ids:
            user_sql_template = "SELECT user_id, name, review_count, average_stars FROM user WHERE user_id IN ({placeholders})"
            for chunk in chunked(user_ids, size=800):
                placeholders = ",".join(["?"] * len(chunk))
                sql = user_sql_template.format(placeholders=placeholders)
                for ur in user_conn.execute(sql, chunk).fetchall():
                    users[ur["user_id"]] = dict(ur)

        merged = []
        for uid, st in user_stats.items():
            u = users.get(uid, {"user_id": uid, "name": None, "review_count": None, "average_stars": None})
            merged.append({
                "user_id": uid,
                "name": u.get("name"),
                "review_count": u.get("review_count"),
                "average_stars": u.get("average_stars"),
                "mentions": st["mentions"],
                "hotels_reviewed": len(st["business_ids"]),
                "example_snippets": st["example_snippets"]
            })

        merged.sort(key=lambda x: (-x["mentions"], -int(x["review_count"] or 0)))

        print("\n=== Users whose reviews mention 'clean' or 'comfortable' (top 50) ===")
        for x in merged[:50]:
            print(f"- {x['name']} (user_id={x['user_id']}) | mentions={x['mentions']} | hotels_reviewed={x['hotels_reviewed']} | review_count={x['review_count']} | avg_stars={x['average_stars']}")
            for snip in x["example_snippets"]:
                print(f"    snippet: {snip}")

    finally:
        biz_conn.close()
        rev_conn.close()
        user_conn.close()

if __name__ == "__main__":
    main()

